"""Main module - entry point."""


def main():
    """Main function."""
    print("Demo project for code refactoring")

if __name__ == "__main__":
    main()

"""String utilities with intentional errors."""


def reverse_string(s):
    """Reverse a string."""
    return s[::-1]


def count_vowels(text):
    """Count vowels in text."""
    vowels = 'aeiouAEIOU'
    count = 0
    for char in text:
        if char in vowels:
            count += 1
    return count


def format_name(first, last):
    """Format full name."""
    return f"{first} {last}"


def duplicate_string(s, n):
    """Duplicate string n times."""
    if not isinstance(n, int):
        raise ValueError("n must be an integer.")
    if n < 0:
        raise ValueError("n must be a non-negative integer.")
    return s * n


def split_by_delimiter(text, delim=" "):
    """Split text by delimiter."""
    parts = text.split(delim)
    return parts

